import itertools

def solve_m(m):
    edges = list(itertools.combinations(range(m), 2))
    num_edges = len(edges)
    num_colors = m
    triangles = list(itertools.combinations(range(m), 3))

    # Precompute which edges are in which triangle
    triangle_edges = []
    for t in triangles:
        t_edges = []
        for e in itertools.combinations(t, 2):
            # Find index of edge e in edges list
            t_edges.append(edges.index(tuple(sorted(e))))
        triangle_edges.append(t_edges)

    color_map = [-1] * num_edges

    def is_valid(edge_idx, color):
        color_map[edge_idx] = color
        # Check all triangles that are now fully colored
        for t_edges in triangle_edges:
            if edge_idx in t_edges:
                if all(color_map[e] != -1 for e in t_edges):
                    t_colors = {color_map[e] for e in t_edges}
                    if len(t_colors) != 3:
                        color_map[edge_idx] = -1
                        return False

        # To check if all 3-sets are distinct, we need all triangles to be colored
        # But we can check if the current triangle's color set is already used.
        # Wait, we can't do that until the triangle is fully colored.
        # Let's keep track of used color sets.

        # But the condition is: "every subset of 3 colors" must be represented.
        # Since there are (m choose 3) subsets and (m choose 3) triangles,
        # each subset must be represented exactly once.
        # So we can check if the color set of the just-completed triangle
        # has already been used.

        # This check is done inside the loop below.
        return True

    # To track used color sets
    used_color_sets = set()

    def backtrack(edge_idx):
        if edge_idx == num_edges:
            return True

        for color in range(num_colors):
            color_map[edge_idx] = color

            # Check if any triangle is completed and if its colors are valid
            valid = True
            completed_triangles = []
            for t_edges in triangle_edges:
                if edge_idx in t_edges and all(color_map[e] != -1 for e in t_edges):
                    t_colors = tuple(sorted({color_map[e] for e in t_edges}))
                    if len(t_colors) != 3 or t_colors in used_color_sets:
                        valid = False
                        break
                    completed_triangles.append(t_colors)

            if valid:
                for tc in completed_triangles:
                    used_color_sets.add(tc)
                if backtrack(edge_idx + 1):
                    return True
                for tc in completed_triangles:
                    used_color_sets.remove(tc)

            color_map[edge_idx] = -1
        return False

    if backtrack(0):
        return True
    return False

for m in range(3, 6):
    print(f"m={m}: {solve_m(m)}")

